<form class="card mb-4 grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-4 xl:grid-cols-8" @submit.prevent="search()" x-data="{ ref: null }" x-init="ref = await $store.app.reference()">
    <div class="sm:col-span-2"><label class="label" for="sf-q">Plate or reference</label><input id="sf-q" class="input" x-model="filters.{{ $qKey ?? 'q' }}" placeholder="e.g. CAB-1234" maxlength="30"></div>
    <div><label class="label" for="sf-s">Status</label><select id="sf-s" class="input" x-model="filters.status">
        <option value="">{{ $defaultStatusLabel ?? 'Open (parked)' }}</option><option value="active">Parked</option><option value="exit_authorized">Gate Authorized</option><option value="completed">Checked out</option><option value="cancelled">Cancelled</option></select></div>
    <div><label class="label" for="sf-c">Vehicle</label><select id="sf-c" class="input" x-model="filters.vehicle_category"><option value="">All</option><template x-for="c in ref?.vehicle_categories || []" :key="c.code"><option :value="c.code" x-text="c.name"></option></template></select></div>
    <div><label class="label" for="sf-f">Fuel</label><select id="sf-f" class="input" x-model="filters.fuel_type"><option value="">All</option><template x-for="f in ref?.fuel_types || []" :key="f.value"><option :value="f.value" x-text="f.label"></option></template></select></div>
    <div><label class="label" for="sf-p">Payment</label><select id="sf-p" class="input" x-model="filters.payment_status"><option value="">Any</option><template x-for="p in ref?.session_filters?.payment_statuses || []" :key="p"><option :value="p" x-text="$fmt.stateLabel('payment', p)"></option></template></select></div>
    <div><label class="label" for="sf-d">{{ $dateLabel ?? 'Entry date' }}</label><input id="sf-d" type="date" class="input" x-model="filters.date"></div>
    <div class="flex items-end gap-2"><button class="btn-primary flex-1">Filter</button><button type="button" class="btn-secondary" @click="reset()">Reset</button></div>
</form>
